def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==0 and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            minr=min(x for x,y in cells); maxr=max(x for x,y in cells)
            minc=min(y for x,y in cells); maxc=max(y for x,y in cells)
            # Mark upper, internally bounded zero pockets with 7.
            if minr==0 and minc>0 and maxc<w-1:
